{
  "status": "AUTHORIZED_UNIQUE",
  "coverage": [
    {
      "text": "别被我这句话的顺序带跑：",
      "role": "CONTEXT",
      "explanation": "This is a meta warning not to use the sentence's textual order as execution order. It adds no executable action, but it requires the ordinal labels in the following clauses to govern ordering."
    },
    {
      "text": "往前走",
      "role": "ACTION",
      "explanation": "This requests a walk_forward action. Its distance is supplied by the following quantity, and its execution position is supplied by the later relation '放第二步'."
    },
    {
      "text": "6米",
      "role": "QUANTITY",
      "explanation": "This supplies distance_m = 6.0 meters for the walk_forward action; 米 is meters, so no conversion is needed."
    },
    {
      "text": "放第二步",
      "role": "RELATION",
      "explanation": "This assigns the immediately preceding walk_forward action to step position 2, overriding any default reading by textual order."
    },
    {
      "text": "，",
      "role": "SEPARATOR",
      "explanation": "This punctuation separates the two clauses and has no executable effect."
    },
    {
      "text": "第一步是",
      "role": "RELATION",
      "explanation": "This assigns the following turn action to step position 1, establishing it as the first executed step."
    },
    {
      "text": "左转",
      "role": "ACTION",
      "explanation": "This requests a turn action. Left direction is positive, and the angle magnitude is supplied by the following quantity."
    },
    {
      "text": "45度",
      "role": "QUANTITY",
      "explanation": "This supplies angle_deg = 45.0 for the turn action. Left is positive, and 45 degrees is within the maximum absolute angle."
    },
    {
      "text": "。",
      "role": "SEPARATOR",
      "explanation": "This sentence terminator closes the instruction and has no executable effect."
    }
  ],
  "dimensions": {
    "action_multiplicity": {
      "status": "UNIQUE",
      "explanation": "The source requests exactly two actions: one turn left 45 degrees and one walk_forward 6 meters. There are no additional actions, repetitions, or omitted executable actions."
    },
    "action_order": {
      "status": "UNIQUE",
      "explanation": "The source explicitly warns not to follow textual order, then labels the walk_forward clause as second step and the left-turn clause as first step. Therefore the unique execution order is turn left 45 degrees first, then walk_forward 6 meters."
    },
    "correction_scope": {
      "status": "UNIQUE",
      "explanation": "There is no edit or correction replacing a prior action or parameter. The warning about sentence order changes how order is interpreted but does not correct or remove an action."
    },
    "repetition_scope": {
      "status": "UNIQUE",
      "explanation": "No repetition or repeated execution is requested. Each of the two actions occurs exactly once."
    },
    "reference_resolution": {
      "status": "UNIQUE",
      "explanation": "The ordinal reference '第二步' attaches to the immediately preceding walk_forward 6 meters action, and '第一步是' attaches to the following left-turn 45 degrees action. No other referents are available or needed."
    },
    "temporal_relations": {
      "status": "UNIQUE",
      "explanation": "The ordinal labels provide a single linear order: step 1 is left turn 45 degrees, step 2 is walk_forward 6 meters. No waiting, simultaneity, or extra timing is specified."
    },
    "unresolved_relations": {
      "status": "UNIQUE",
      "explanation": "The source does not explicitly leave any order, scope, action, parameter, or relationship unresolved. The only unusual relation is the meta warning against textual order, and the ordinal labels fully resolve the intended order."
    }
  },
  "authorized_plan": [
    {
      "id": "s1",
      "skill": "turn",
      "parameters": {
        "angle_deg": 45.0
      },
      "depends_on": []
    },
    {
      "id": "s2",
      "skill": "walk_forward",
      "parameters": {
        "distance_m": 6.0
      },
      "depends_on": [
        "s1"
      ]
    }
  ]
}
